function gen() {
    for ($i = 0; $i < 3; $i++) yield $i;
}
foreach (gen() as $v) echo $v; // 012

function inner() { yield 1; yield 2; }
function outer() {
    yield 0;
    yield from inner(); // отдали всё из inner
    yield 3;
}
foreach (outer() as $v) echo $v; // 0123

function g() {
    $x = yield 'ready';
    echo "got $x";
}
$gen = g();
$gen->current();       // 'ready' (запустили вручную)
$gen->send('hello');   // выведет: got hello

class Bag implements IteratorAggregate {
    private $items = [1, 2, 3];
    public function getIterator(): Iterator {
        return new ArrayIterator($this->items);
    }
}
foreach (new Bag() as $v) echo $v; // 123

class Adder {
    public function __construct(private int $n) {}
    public function __invoke($x) { return $x + $this->n; }
}
$add5 = new Adder(5);
echo $add5(10); // 15 (вызвали объект как функцию)

